/*
 * app.js
 * Static mentor discovery view implementation.
 */

const mentors = [
  {
    id: 'mentor-1',
    name: '김서연',
    role: '프로덕트 디자이너',
    avatar: 'assets/reference/avatar-1.png',
    certification: { label: 'UX 전문가', color: '#6b46c1' }, // Purple
    employer: { label: '현재: 테크 주식회사', color: '#2563eb' }, // Blue
    description: '사용자 경험 개선과 데이터 기반 디자인 의사결정을 전문으로 합니다. 복잡한 시스템을 직관적인 인터페이스로 변환하는 데 중점을 둡니다.',
    isFavorite: false
  },
  {
    id: 'mentor-2',
    name: '박민준',
    role: '프론트엔드 개발자',
    avatar: 'assets/reference/avatar-2.png',
    certification: { label: 'AWS 솔루션 아키텍트', color: '#6b46c1' }, // Purple
    employer: { label: '현재: 클라우드 스타트업', color: '#2563eb' }, // Blue
    description: '반응형 웹 애플리케이션 및 고성능 UI 구현에 대한 깊은 이해를 가지고 있습니다. 접근성과 성능 최적화를 중요하게 생각합니다.',
    isFavorite: false
  }
];

function renderStaticView() {
  const list = document.getElementById('mentor-list');
  if (!list) return;

  // Render Mentor Cards
  mentors.forEach(mentor => {
    const card = document.createElement('article');
    card.className = 'mentor-card';
    card.dataset.id = mentor.id;

    // Header: Avatar, Name, Role, Favorite
    const header = document.createElement('div');
    header.className = 'card-header';

    const avatar = document.createElement('img');
    avatar.src = mentor.avatar;
    avatar.alt = `${mentor.name} 프로필`;
    avatar.className = 'mentor-avatar';

    const info = document.createElement('div');
    info.className = 'mentor-info';

    const name = document.createElement('h2');
    name.textContent = mentor.name;
    name.className = 'mentor-name';

    const role = document.createElement('p');
    role.textContent = mentor.role;
    role.className = 'mentor-role';

    info.appendChild(name);
    info.appendChild(role);

    const favBtn = document.createElement('button');
    favBtn.type = 'button';
    favBtn.className = 'favorite-btn';
    favBtn.setAttribute('aria-label', `${mentor.name} 즐겨찾기`);
    // Using a simple SVG heart for the static state, relying on CSS for visual
    favBtn.innerHTML = '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M20.84 4.61a5.5 5.5 0 0 0-7.78 0L12 5.67l-1.06-1.06a5.5 5.5 0 0 0-7.78 7.78l1.06 1.06L12 21.23l7.78-7.78 1.06-1.06a5.5 5.5 0 0 0 0-7.78z"></path></svg>';

    header.appendChild(avatar);
    header.appendChild(info);
    header.appendChild(favBtn);

    // Metadata: Certification & Employer
    const meta = document.createElement('div');
    meta.className = 'mentor-meta';

    const certBadge = document.createElement('span');
    certBadge.textContent = mentor.certification.label;
    certBadge.style.backgroundColor = `${mentor.certification.color}20`; // 20% opacity
    certBadge.style.color = mentor.certification.color;
    certBadge.className = 'badge';

    const empBadge = document.createElement('span');
    empBadge.textContent = mentor.employer.label;
    empBadge.style.backgroundColor = `${mentor.employer.color}20`;
    empBadge.style.color = mentor.employer.color;
    empBadge.className = 'badge';

    meta.appendChild(certBadge);
    meta.appendChild(empBadge);

    // Description
    const desc = document.createElement('p');
    desc.textContent = mentor.description;
    desc.className = 'mentor-desc';

    // Footer: Fee/Action (Static placeholder as per contract)
    const footer = document.createElement('div');
    footer.className = 'card-footer';

    const fee = document.createElement('span');
    fee.textContent = '상담료';
    fee.className = 'fee-label';

    const actionBtn = document.createElement('button');
    actionBtn.type = 'button';
    actionBtn.className = 'action-btn';
    actionBtn.textContent = '상담 신청';
    actionBtn.disabled = true; // Static example controls are disabled

    footer.appendChild(fee);
    footer.appendChild(actionBtn);

    card.appendChild(header);
    card.appendChild(meta);
    card.appendChild(desc);
    card.appendChild(footer);
    list.appendChild(card);
  });
}

completed.layout:
:root {
  --color-bg: #f3e8ff;
  --color-surface: #ffffff;
  --color-text-heading: #111827;
  --color-text-body: #374151;
  --color-text-muted: #6b7280;
  --color-accent-purple: #6b46c1;
  --color-accent-blue: #2563eb;
  --color-border: #e5e7eb;

  --font-sans: 'Pretendard', -apple-system, BlinkMacSystemFont, system-ui, Roboto, 'Helvetica Neue', Arial, sans-serif;

  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;

  --shadow-card: 0 1px 3px rgba(0, 0, 0, 0.05), 0 1px 2px rgba(0, 0, 0, 0.03);
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

body {
  margin: 0;
  padding: 0;
  font-family: var(--font-sans);
  font-size: 14px;
  line-height: 1.5;
  color: var(--color-text-body);
  background-color: var(--color-bg);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

.container {
  width: 100%;
  max-width: 430px;
  margin: 0 auto;
  padding: var(--space-lg) var(--space-md);
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.page-title {
  font-size: 24px;
  font-weight: 700;
  line-height: 1.3;
  color: var(--color-text-heading);
  margin: 0;
}

.search-wrapper {
  position: relative;
  width: 100%;
}

.search-wrapper input {
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  font-size: 16px;
  line-height: 1.5;
  border: 1px solid var(--color-border);
  border-radius: var(--radius-md);
  background-color: var(--color-surface);
  color: var(--color-text-body);
  outline: none;
}

.search-wrapper input::placeholder {
  color: var(--color-text-muted);
}

.category-chips {
  display: flex;
  gap: var(--space-sm);
  overflow-x: auto;
  padding-bottom: var(--space-xs);
  -ms-overflow-style: none;
  scrollbar-width: none;
}

.category-chips::-webkit-scrollbar {
  display: none;
}

.chip {
  flex-shrink: 0;
  padding: var(--space-xs) var(--space-sm);
  font-size: 13px;
  font-weight: 500;
  line-height: 1.4;
  border: 1px solid var(--color-border);
  border-radius: 100px;
  background-color: var(--color-surface);
  color: var(--color-text-body);
  cursor: pointer;
  transition: all 0.2s ease;
}

.chip.active {
  background-color: var(--color-text-heading);
  color: var(--color-surface);
  border-color: var(--color-text-heading);
}

.mentor-grid {
  display: flex;
  flex-direction: column;
  gap: var(--space-lg);
}

.mentor-card {
  background-color: var(--color-surface);
  border-radius: var(--radius-lg);
  padding: var(--space-md);
  box-shadow: var(--shadow-card);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
}

.card-header {
  display: flex;
  align-items: flex-start;
  gap: var(--space-sm);
}

.mentor-avatar {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  object-fit: cover;
  flex-shrink: 0;
  background-color: #f9fafb;
}

.mentor-info {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  min-width: 0;
  flex-grow: 1;
}

.mentor-name {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  color: var(--color-text-heading);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mentor-role {
  font-size: 14px;
  font-weight: 500;
  line-height: 1.4;
  color: var(--color-text-muted);
  margin: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.favorite-btn {
  flex-shrink: 0;
  width: 32px;
  height: 32px;
  display: flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: transparent;
  color: var(--color-text-muted);
  cursor: pointer;
  padding: 0;
  transition: color 0.2s ease;
}

.favorite-btn:hover {
  color: #ef4444;
}

.favorite-btn svg {
  width: 20px;
  height: 20px;
}

.mentor-meta {
  display: flex;
  gap: var(--space-sm);
  flex-wrap: wrap;
}

.badge {
  font-size: 12px;
  font-weight: 500;
  line-height: 1.4;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 6px;
  display: inline-flex;
  align-items: center;
}

.badge.certification {
  background-color: rgba(107, 70, 193, 0.1);
  color: var(--color-accent-purple);
}

.badge.employer {
  background-color: rgba(37, 99, 235, 0.1);
  color: var(--color-accent-blue);
}

.mentor-desc {
  font-size: 14px;
  line-height: 1.6;
  color: var(--color-text-body);
  margin: 0;
  word-break: keep-all;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: var(--space-sm);
  border-top: 1px solid var(--color-border);
  margin-top: var(--space-xs);
}

.fee-label {
  font-size: 13px;
  font-weight: 500;
  color: var(--color-text-muted);
}

.action-btn {
  padding: var(--space-sm) var(--space-md);
  font-size: 14px;
  font-weight: 600;
  line-height: 1.4;
  background-color: var(--color-text-heading);
  color: var(--color-surface);
  border: none;
  border-radius: var(--radius-sm);
  cursor: pointer;
  transition: opacity 0.2s ease;
}

.action-btn:hover:not(:disabled) {
  opacity: 0.9;
}

.action-btn:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.page-footer {
  font-size: 12px;
  color: var(--color-text-muted);
  text-align: center;
  margin-top: var(--space-md);
}

completed.responsive:
/* Form and Input States */
.search-wrapper input:focus {
  border-color: var(--color-accent-purple);
  box-shadow: 0 0 0 2px rgba(107, 70, 193, 0.2);
}

.chip:focus-visible {
  outline: 2px solid var(--color-accent-purple);
  outline-offset: 2px;
}

.favorite-btn:focus-visible {
  outline: 2px solid var(--color-accent-purple);
  outline-offset: 2px;
  border-radius: 50%;
}

.action-btn:focus-visible {
  outline: 2px solid var(--color-text-heading);
  outline-offset: 2px;
}

/* Disabled and Static States */
.chip[disabled],
.action-btn[disabled] {
  opacity: 0.5;
  cursor: not-allowed;
  pointer-events: none;
}

[hidden] {
  display: none !important;
}

/* Reduced Motion */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

/* Mobile 390px Adaptation */
@media (max-width: 390px) {
  .container {
    padding: var(--space-md);
    gap: var(--space-lg);
  }

  .mentor-card {
    padding: var(--space-sm);
  }

  .card-footer {
    flex-direction: column;
    align-items: stretch;
    gap: var(--space-sm);
    text-align: center;
  }

  .action-btn {
    width: 100%;
  }
}

/* Mobile 320px Adaptation */
@media (max-width: 320px) {
  .page-title {
    font-size: 20px;
  }

  .category-chips {
    gap: var(--space-xs);
  }

  .chip {
    padding: var(--space-xs) var(--space-xs);
    font-size: 12px;
  }

  .mentor-info {
    gap: 0;
  }

  .mentor-name {
    font-size: 15px;
  }

  .badge {
    font-size: 11px;
    padding: 2px 6px;
  }
}
